import React, { useState } from 'react';
import InputSection from './components/InputSection';
import SummarySection from './components/SummarySection';
import Scorecard from './components/Scorecard';
import ModelSelector from './components/ModelSelector';
import { generateMeetingSummary, evaluateSummaryQuality } from './services/geminiService';
import { EvaluationResult, LoadingState, GeminiModel } from './types';

const DEFAULT_TRANSCRIPT = `Speaker 1: Alright, let's get started. The main goal today is to finalize the launch date for the mobile app.
Speaker 2: I've spoken with the dev team. They still need about two weeks to clear the critical bugs in the login module.
Speaker 1: Two weeks? That pushes us past our Q3 deadline.
Speaker 2: Yes, but if we launch now, user retention will suffer. It's better to delay.
Speaker 3: Marketing is ready to go, but we can pause the ad spend. I agree, quality first.
Speaker 1: Okay. Let's officially move the launch date to October 15th.
Speaker 2: I'll notify the engineering team.
Speaker 3: I will update the social media calendar.
Speaker 1: Great. Also, we need to hire a new QA lead by next Friday.
Speaker 2: Agreed. I'll post the job listing tomorrow.`;

const App: React.FC = () => {
  const [transcript, setTranscript] = useState<string>(DEFAULT_TRANSCRIPT);
  const [summary, setSummary] = useState<string>('');
  const [evaluation, setEvaluation] = useState<EvaluationResult | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [error, setError] = useState<string | null>(null);

  // Model Selection State
  const [generatorModel, setGeneratorModel] = useState<GeminiModel>('gemini-3-flash-preview');
  const [judgeModel, setJudgeModel] = useState<GeminiModel>('gemini-3-pro-preview');

  const handleGenerateSummary = async () => {
    setError(null);
    setLoadingState(LoadingState.GENERATING_SUMMARY);
    setEvaluation(null); 

    try {
      const generatedSummary = await generateMeetingSummary(transcript, generatorModel);
      setSummary(generatedSummary);
    } catch (err) {
      setError("Failed to generate summary. Please try again.");
    } finally {
      setLoadingState(LoadingState.IDLE);
    }
  };

  const handleEvaluateSummary = async () => {
    if (!summary || !transcript) return;

    setError(null);
    setLoadingState(LoadingState.EVALUATING);

    try {
      const result = await evaluateSummaryQuality(transcript, summary, judgeModel);
      setEvaluation(result);
    } catch (err) {
      setError("Failed to evaluate the summary. Please try again.");
    } finally {
      setLoadingState(LoadingState.IDLE);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-8 px-4 sm:px-6 lg:px-8 font-sans">
      <div className="max-w-6xl mx-auto space-y-8">

        {/* Header */}
        <header className="text-center mb-6">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight sm:text-5xl mb-2">
            Judge<span className="text-brand-600">Genie</span>
          </h1>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            LLM-as-a-Judge framework for quality assurance.
          </p>
        </header>

        {/* Configuration Bar */}
        <ModelSelector 
          generatorModel={generatorModel} 
          setGeneratorModel={setGeneratorModel}
          judgeModel={judgeModel}
          setJudgeModel={setJudgeModel}
          disabled={loadingState !== LoadingState.IDLE}
        />

        {/* Error Banner */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-md animate-bounce-slight">
            <div className="flex">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-red-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm text-red-700 font-medium">{error}</p>
              </div>
            </div>
          </div>
        )}

        {/* Main Workspace */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-[500px]">
          <InputSection 
            transcript={transcript} 
            setTranscript={setTranscript} 
            onGenerate={handleGenerateSummary}
            loadingState={loadingState}
          />
          <SummarySection 
            summary={summary}
            setSummary={setSummary}
            onEvaluate={handleEvaluateSummary}
            loadingState={loadingState}
            hasEvaluated={!!evaluation}
          />
        </div>

        {/* Scorecard Results */}
        {(evaluation || loadingState === LoadingState.EVALUATING) && (
          <div id="scorecard-section">
            <Scorecard 
              evaluation={evaluation} 
              onUpdate={setEvaluation}
              isLoading={loadingState === LoadingState.EVALUATING}
            />
          </div>
        )}

      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { LoadingState } from '../types';

interface SummarySectionProps {
  summary: string;
  setSummary: (summary: string) => void;
  onEvaluate: () => void;
  loadingState: LoadingState;
  hasEvaluated: boolean;
}

const SummarySection: React.FC<SummarySectionProps> = ({ 
  summary, 
  setSummary,
  onEvaluate, 
  loadingState,
  hasEvaluated
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const isEvaluating = loadingState === LoadingState.EVALUATING;

  useEffect(() => {
    if (loadingState === LoadingState.GENERATING_SUMMARY) {
      setIsEditing(false);
    }
  }, [loadingState]);

  if (!summary && !isEditing) {
    return (
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 h-full flex flex-col items-center justify-center text-center min-h-[300px]">
        <div className="bg-slate-100 p-4 rounded-full mb-4">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
        </div>
        <h3 className="text-lg font-medium text-slate-900">No Summary Yet</h3>
        <p className="text-slate-500 mt-2 max-w-xs mb-6 text-sm">Generate a summary from the transcript or paste your own notes to enable the AI Judge.</p>

        <button 
          onClick={() => setIsEditing(true)}
          className="text-brand-600 font-medium hover:text-brand-700 flex items-center gap-1 text-sm"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
          </svg>
          Manually input notes
        </button>
      </div>
    );
  }

  const renderContent = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return (
      <div className="whitespace-pre-wrap font-sans text-slate-700 leading-relaxed text-sm">
        {parts.map((part, index) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
          }
          return <span key={index}>{part}</span>;
        })}
