            {judgeModel === 'gemini-3-pro-preview' && "Uses 32k Thinking Budget for verification."}
            {judgeModel === 'gemini-3-flash-preview' && "Rapid results with standard logic."}
          </p>
        </div>
      </div>
    </div>
  );
};

export default ModelSelector;

import { GoogleGenAI, Type, type Schema } from "@google/genai";
import { EvaluationResult, GeminiModel } from "../types";

const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Generates a summary using the selected model.
 */
export const generateMeetingSummary = async (transcript: string, model: GeminiModel): Promise<string> => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: model,
      contents: `You are a professional scribe. Create a detailed summary from this meeting transcript.

      Structure:
      - **Meeting Notes**: Synthesize key discussions.
      - **Action Items**: Explicit task list with owners.

      Transcript:
      ${transcript}`,
      config: {
        temperature: 0.2,
        ...(model === 'gemini-3-pro-preview' ? { thinkingConfig: { thinkingBudget: 4000 } } : {})
      }
    });

    if (response.text) {
      return response.text;
    }
    throw new Error("Empty response from Generator");
  } catch (error) {
    console.error("Generator Error:", error);
    throw error;
  }
};

/**
 * Evaluates the summary using the selected judge model.
 */
export const evaluateSummaryQuality = async (
  originalTranscript: string,
  generatedSummary: string,
  model: GeminiModel
): Promise<EvaluationResult> => {
  try {
    const ai = getAiClient();
    const evaluationSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        accuracy: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            reasoning: { type: Type.STRING },
          },
          required: ["score", "reasoning"],
        },
        completeness: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            reasoning: { type: Type.STRING },
          },
          required: ["score", "reasoning"],
        },
        coverage: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            reasoning: { type: Type.STRING },
          },
          required: ["score", "reasoning"],
        },
        structure: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            reasoning: { type: Type.STRING },
          },
          required: ["score", "reasoning"],
        },
        overallScore: { type: Type.NUMBER },
        overallComment: { type: Type.STRING },
      },
      required: ["accuracy", "completeness", "coverage", "structure", "overallScore", "overallComment"],
    };

    const response = await ai.models.generateContent({
      model: model,
      contents: `You are a Senior Quality Auditor for AI-generated content. 

      TASK:
      Evaluate the "Generated Summary" against the "Original Transcript".

      METRIC DEFINITIONS:
      1. Accuracy: No hallucinations. Are facts/attributions correct?
      2. Completeness: Were any critical decisions or dates mentioned in the transcript omitted?
      3. Coverage: Does the summary capture the full BREADTH of the meeting topics? Or did it hyper-focus on one part while ignoring the rest?
      4. Structure: Is the formatting logical and easy to read?

      ORIGINAL TRANSCRIPT:
      ${originalTranscript}

      GENERATED SUMMARY:
      ${generatedSummary}

      Output JSON only.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: evaluationSchema,
        temperature: 0.1,
        // Using high thinking budget to simulate "GPT-4 Level" reasoning depth
        ...(model === 'gemini-3-pro-preview' ? { thinkingConfig: { thinkingBudget: 32768 } } : {})
      }
    });

    let jsonText = response.text || "";
    const cleanedJson = jsonText.replace(/```json|```/g, "").trim();
    return JSON.parse(cleanedJson) as EvaluationResult;

  } catch (error) {
    console.error("Judge Error:", error);
    throw error;
  }
};
